    sBoundingBox.nLeft = nX - (nVectorX >> 1);
    sBoundingBox.nRight = sBoundingBox.nLeft - 1 + nVectorX;
    sBoundingBox.nBottom = nY - (nVectorY >> 1);
    sBoundingBox.nTop = sBoundingBox.nBottom - 1 + nVectorY;
    RemoveCollision_BoundingBox(pRoom, &sBoundingBox, eCollisionFlag);
