    D2RoomStrc* pResultRoom = GetFreeCoordinates(pRoom, pPoint, nullptr, nUnitSize, eCollisionFlag, eCollisionFlag, bAllowNeighboorRooms, nMaxDistance, 1);
    return pResultRoom;
